"""
Where ES-DE and Steam ROM Manager look for each game's images and videos.
"""

from pathlib import Path

from modules import settings
from modules import esde

IMAGE_SUFFIXES = (".png", ".jpg", ".jpeg", ".webp")
VIDEO_SUFFIXES = (".mp4", ".mkv", ".avi", ".wmv", ".mov", ".webm", ".m4v")

# ES-DE's media folders and the files each accepts. The app downloads covers,
# screenshots, title screens, marquees and fan art itself; Skyscraper adds the
# rest. Miximages are generated by ES-DE from these.
ESDE_MEDIA_TYPES = {
    "covers": IMAGE_SUFFIXES,
    "screenshots": IMAGE_SUFFIXES,
    "titlescreens": IMAGE_SUFFIXES,
    "marquees": IMAGE_SUFFIXES,
    "fanart": IMAGE_SUFFIXES,
    "backcovers": IMAGE_SUFFIXES,
    "3dboxes": IMAGE_SUFFIXES,
    "physicalmedia": IMAGE_SUFFIXES,
    "miximages": IMAGE_SUFFIXES,
    "videos": VIDEO_SUFFIXES,
    "manuals": (".pdf",),
}

# Steam ROM Manager's local image kinds: library capsule, wide capsule, hero
# banner, logo and icon. SRM accepts PNG, JPG and TGA.
STEAM_IMAGE_TYPES = ("tall", "long", "hero", "logo", "icon")
STEAM_SUFFIXES = (".png", ".jpg")


def esde_media_name(game_path):
    """
    ES-DE names media after the game file without its extension, but keeps the
    "extension" of a folder it interprets as a file: "Game.cue/" -> "Game.cue".
    """
    game_path = Path(game_path)
    return game_path.name if game_path.is_dir() else game_path.stem


def esde_media_path(media_root, system, game_path, media_type, suffix):
    return Path(media_root) / system / media_type / f"{esde_media_name(game_path)}{suffix}"


def has_esde_media(media_root, system, game_path, media_type):
    return any(
        esde_media_path(media_root, system, game_path, media_type, suffix).exists()
        for suffix in ESDE_MEDIA_TYPES[media_type]
    )


def steam_artwork_root():
    """Defaults to a steam-artwork folder beside ES-DE's media folder."""
    return settings.path("steam_artwork_dir") or esde.media_root().parent / "steam-artwork"


def steam_artwork_path(root, system, game_path, kind, suffix):
    """Steam ROM Manager matches local images by ${fileName}: the file name without its extension."""
    return Path(root) / system / kind / f"{Path(game_path).stem}{suffix}"


def has_steam_artwork(root, system, game_path, kind):
    return any(
        steam_artwork_path(root, system, game_path, kind, suffix).exists()
        for suffix in STEAM_SUFFIXES
    )


def media_coverage(games, media_root, steam_root):
    """
    For each media type, how many of games have it, per system and overall:
    {"total": n, "by_type": {type: count}, "by_system": {system: {"games": n, type: count}}}.
    games is a list of (system, game_path).
    """
    types = [*ESDE_MEDIA_TYPES, *(f"steam_{kind}" for kind in STEAM_IMAGE_TYPES)]
    by_type = dict.fromkeys(types, 0)
    by_system = {}

    for system, game_path in games:
        row = by_system.setdefault(system, {"games": 0, **dict.fromkeys(types, 0)})
        row["games"] += 1

        for media_type in ESDE_MEDIA_TYPES:
            if has_esde_media(media_root, system, game_path, media_type):
                row[media_type] += 1
                by_type[media_type] += 1

        for kind in STEAM_IMAGE_TYPES:
            if has_steam_artwork(steam_root, system, game_path, kind):
                row[f"steam_{kind}"] += 1
                by_type[f"steam_{kind}"] += 1

    return {"total": len(games), "by_type": by_type, "by_system": by_system}
